package cn.workbench;
import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@RestController @RequestMapping("/api/v1") public class TaskController {
 final TaskService tasks;final Policy policy;final Writes writes;final Records records;final Store db;
 public TaskController(TaskService t,Policy p,Writes w,Records r,Store d){tasks=t;policy=p;writes=w;records=r;db=d;}
 @GetMapping("/tasks") Object list(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String status,@RequestParam(required=false)String keyword){var items=tasks.tasks(policy.actor(q));if(status!=null&&!status.isBlank())items=items.stream().filter(t->status.equals(t.get("status"))).toList();if(keyword!=null&&!keyword.isBlank())items=items.stream().filter(t->String.valueOf(t.get("title")).contains(keyword)).toList();return Api.ok(page(items,page,pageSize));}
 @GetMapping("/tasks/{id}") Object detail(@PathVariable long id,HttpServletRequest q){return Api.ok(tasks.detail(policy.actor(q),id));}
 @PostMapping("/tasks") Object create(@RequestBody Map<String,Object>b,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,b,()->tasks.create(a,b));}
 @PostMapping("/tasks/{id}/{action:confirm-assign|accept|reject|cancel|deadline|summarize|urge}") Object action(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var b=body==null?new LinkedHashMap<String,Object>():body;var a=policy.actor(q);return writes.run(q,b,()->tasks.taskAction(a,id,action,b));}
 @GetMapping("/sub-tasks/mine") Object mine(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){var a=policy.actor(q);var list=records.list("SUB_TASK",a.company(),a.leader()?null:a.dept()).stream().filter(s->{try{policy.subtask(a,s,false);return true;}catch(ApiException e){return false;}}).map(s->{var c=new LinkedHashMap<>(s);var t=records.get(Jsons.number(s.get("taskId")));c.put("taskTitle",t.get("title"));c.put("title",t.get("title"));c.put("allowedActions",tasks.subActions(a,t,s));return (Map<String,Object>)c;}).toList();return Api.ok(page(list,page,pageSize));}
 @PostMapping("/sub-tasks/{id}/{action:receive|assign|progress|submit|withdraw|extend|transfer}") Object sub(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var b=body==null?new LinkedHashMap<String,Object>():body;var a=policy.actor(q);return writes.run(q,b,()->tasks.subAction(a,id,action,b));}
 @PostMapping("/tasks/{id}/comments") Object comment(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,b,()->tasks.comment(a,id,b));}
 @GetMapping("/collaborations") Object collaborations(HttpServletRequest q){return Api.ok(tasks.collaborations(policy.actor(q)));}
 @PostMapping("/collaborations/{id}/{action:accept|reject}") Object collaboration(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var a=policy.actor(q);var b=body==null?new LinkedHashMap<String,Object>():body;return writes.run(q,b,()->tasks.collaboration(a,id,action,b));}
 @PostMapping("/deadline-requests/{id}/{action:approve|reject}") Object deadline(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var a=policy.actor(q);var b=body==null?new LinkedHashMap<String,Object>():body;return writes.run(q,b,()->tasks.deadline(a,id,action,b));}
 @GetMapping("/notifications") Object notifications(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)Boolean read){var a=policy.actor(q);return Api.ok(page(db.notifications(a.uid()).stream().filter(n->(Objects.equals(a.company(),Jsons.integer(n.get("companyId")))||a.role().equals("GROUP_LEADER"))&&(n.get("taskId")==null||policy.canSeeTask(a,records.get(Jsons.number(n.get("taskId")))))).filter(n->read==null||read.equals(n.get("isRead"))).toList(),page,pageSize));}
 @PostMapping("/notifications/{id}/read") Object read(@PathVariable long id,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,Map.of(),()->{var target=db.notifications(a.uid()).stream().filter(n->Jsons.number(n.get("id"))==id).findFirst().orElseThrow(ApiException::denied);if(!(Objects.equals(a.company(),Jsons.integer(target.get("companyId")))||a.role().equals("GROUP_LEADER"))||target.get("taskId")!=null&&!policy.canSeeTask(a,records.get(Jsons.number(target.get("taskId")))))throw ApiException.denied();if(db.readNotification(id,a.uid())!=1)throw ApiException.denied();return Map.of();});}
 @PostMapping("/notifications/archive") Object archive(HttpServletRequest q){var a=policy.actor(q);return writes.run(q,Map.of(),()->{db.archiveNotifications(a.uid());return Map.of();});}
 public static Map<String,Object> page(List<?> list,int page,int size){if(page<1||size<1||size>100)throw new ApiException(400,"INVALID_PAGE","分页参数范围错误");int from=(int)Math.min((long)(page-1)*size,list.size());return Records.map("items",list.subList(from,Math.min(from+size,list.size())),"page",page,"pageSize",size,"total",list.size());}
}
